  `status` varchar(5) NOT NULL,
  `trx_status` tinyint(1) DEFAULT '0' COMMENT '1=Fetch, 2=Paid',
  `s_time` int NOT NULL,
  `s_date` date NOT NULL,
  `level1` varchar(20) NOT NULL,
  `level2` varchar(20) NOT NULL,
  `level3` varchar(20) NOT NULL,
  `level4` varchar(20) NOT NULL,
  `level5` varchar(20) NOT NULL,
  `ip` varchar(200) NOT NULL DEFAULT '0',
  `rfrom` varchar(50) NOT NULL DEFAULT '0',
  `txnid` varchar(30) DEFAULT NULL,
  `bill_payment_id` varchar(30) DEFAULT '0',
  `bill_refer_id` varchar(50) DEFAULT '0',
  `bill_no` varchar(50) DEFAULT NULL,
  `biller_acc_no` varchar(50) DEFAULT NULL,
  `biller_mobile` varchar(15) DEFAULT NULL,
  `bill_amount` decimal(10,2) DEFAULT '0.00',
  `bill_vat` decimal(10,2) DEFAULT '0.00',
  `vendor_charge` decimal(10,2) DEFAULT '0.00',
  `bill_total_amount` decimal(10,2) DEFAULT '0.00',
  `is_bill_paid` varchar(10) DEFAULT NULL,
  `biller_id` varchar(20) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `hgidx_op_stat` (`status`)
) ENGINE=MyISAM AUTO_INCREMENT=25 DEFAULT CHARSET=latin1;

