--
-- Table structure for table `bkash_balance`
--

DROP TABLE IF EXISTS `bkash_balance`;
CREATE TABLE IF NOT EXISTS `bkash_balance` (
  `id` int NOT NULL AUTO_INCREMENT,
  `user_id` int NOT NULL,
  `amount` int NOT NULL,
  `submitted_date` date NOT NULL,
  `load_by` int NOT NULL,
  `updated` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `note` varchar(200) NOT NULL,
  `ip` varchar(100) NOT NULL,
  `return_payment` int NOT NULL,
  `old_balance` int NOT NULL DEFAULT '0',
  `new_balance` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=196 DEFAULT CHARSET=latin1;

