--
-- Table structure for table `bkash_report`
--

DROP TABLE IF EXISTS `bkash_report`;
CREATE TABLE IF NOT EXISTS `bkash_report` (
  `id` int NOT NULL AUTO_INCREMENT,
  `company` varchar(50) NOT NULL DEFAULT '0',
  `msgbody` varchar(1000) NOT NULL,
  `ucid` varchar(15) NOT NULL,
  `amt` varchar(10) NOT NULL,
  `transactionid` varchar(100) NOT NULL,
  `number` varchar(15) NOT NULL,
  `f_id` varchar(50) NOT NULL,
  `datetime` varchar(100) NOT NULL,
  `status` varchar(50) NOT NULL,
  `balance` varchar(50) NOT NULL,
  `sending_number` varchar(100) NOT NULL,
  `date` date DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=MyISAM AUTO_INCREMENT=1526 DEFAULT CHARSET=latin1;

